<template>
  <AppLoader v-if="isLoading" subject="data" />
  <template v-else>
    <AppError v-if="error" :error="error" title="Failed to load data" />
    <section v-else class="flex flex-col gap-10">
      <PageTitle title="Signatory Verification" />
      <Card class="max-w-md w-full p-6 mx-auto">
        <div class="flex flex-col gap-6">
          <ComboboxSelector
            v-model="projectId"
            :items="projectsList"
            label="Project"
            placeholder="Select a project"
            empty-text="No projects found"
            clearable
            :icon="BriefcaseBusinessIcon"
          />
          <div class="flex flex-col gap-2 items-center">
            <template v-if="selectedProject?.voice_verification_enabled">
              <Button
                variant="default"
                :disabled="!selectedProject || isStartingVerification"
                :loading="isStartingVerification"
                @click="onStartVerification"
              >
                Start Signatory Verification
              </Button>
              <p class="text-small text-accent-foreground pt-1 text-center">
                This action needs device access to capture a short verification sample.
              </p>
              <Separator label="OR" class="my-4" />
            </template>
            <NuxtLink
              :to="
                selectedProject
                  ? { name: 'verification-signatory-create', query: { project_id: selectedProject.value } }
                  : { name: undefined }
              "
            >
              <Button :disabled="!selectedProject">Submit Signatories</Button>
            </NuxtLink>
          </div>
        </div>
      </Card>
    </section>
  </template>
</template>

<script setup lang="ts">
import { useVoiceVerificationStore } from '~/stores/verification/voice';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';
import { BriefcaseBusinessIcon } from 'lucide-vue-next';

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser'],
});

useHead({
  title: 'Signatory Verification',
});

const route = useRoute();
const router = useRouter();

const store = useVoiceVerificationStore();
const { projects, isLoading, error } = useSelectorActiveSignatureProjectList();
const { isTracking, usingMicrophone } = useMobileRuntimeState();
const { isMobile } = useMobileForWeb();
const hasActiveShift = computed(() => isTracking.value);

const voiceVerificationBlocked = computed(() => isMobile && hasActiveShift.value && !usingMicrophone.value);

const projectId = ref<string | null>(null);
const selectedProject = computed<SelectItem | null>(() => {
  return projectsList.value.find((project) => project.value === projectId.value) ?? null;
});

const isStartingVerification = ref<boolean>(false);

const projectsList = computed<SelectItem[]>(() => {
  return projects.value
    ? projects.value.map((project) => {
        return {
          name: project.name,
          value: project.id,
          voice_verification_enabled: project.voice_verification_enabled,
        };
      })
    : [];
});

onMounted(async () => {
  if (route.query.project_id) {
    projectId.value = route.query.project_id as string;
  }
});

async function onStartVerification() {
  if (!selectedProject.value?.value || isStartingVerification.value) return;

  if (voiceVerificationBlocked.value) {
    showToastError(
      'You are trying to start signatory verification while having an active shift on a canvassing project.'
    );
    return;
  }

  try {
    isStartingVerification.value = true;
    const verificationId = await store.createVerification(selectedProject.value.value);
    if (verificationId) await navigateTo({ name: 'verification-voice-id', params: { id: verificationId } });
  } catch (err: any) {
    error.value = err.message ?? 'An error occurred while starting signatory verification.';
  } finally {
    isStartingVerification.value = false;
  }
}
</script>

<style scoped lang="scss"></style>
